  hc_yAxis(title = list(text = "Total Portfolio Value ($)")) |&gt; 
  hc_xAxis(title = list(text = "Date")) |&gt; 
  hc_tooltip(pointFormat = "Value: ${point.y:,.0f}") |&gt; 
