# Portfolio returns (continous returns)
hchart(portfolio, type = "line", hcaes(x = date, y = continuous_return)) |&gt; 
  hc_title(text = "Portfolio Returns Over Time") |&gt; 
  hc_yAxis(title = list(text = "Portfolio Return (%)")) |&gt; 
