The all-in / all-out simulator
A simple state machine: at each date, check the signal and update cash, position, and total_value.

capital   &lt;- 1000000
cash      &lt;- capital
position  &lt;- 0
portfolio &lt;- data.frame()

for (i in seq_len(nrow(etf_signals))) {
  date_i  &lt;- etf_signals$date[i]
  price_i &lt;- etf_signals$adjusted[i]
  sig     &lt;- etf_signals$signal[i]

  if (!is.na(sig)) {
    if (sig == "buy") {
      position &lt;- floor(cash / price_i)
      cash     &lt;- cash - position * price_i
    } else if (sig == "sell") {
      cash     &lt;- cash + position * price_i
      position &lt;- 0
    }
  }
  total_value &lt;- cash + position * price_i
  portfolio   &lt;- bind_rows(portfolio,
                  data.frame(date = date_i, price = price_i,
                             position, cash, total_value))
}

